// Post-processing for the artifacts generated by `npm run generate -w contract`:
// 1. marks every artifact with a do-not-edit header,
// 2. moves the JSON spec copy into server/ (the server imports it as a JSON module at runtime).
// YAML and TypeScript files get comment headers; the JSON copy cannot carry comments,
// so it is marked with a top-level OpenAPI extension key instead.

import { readFile, unlink, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";

const contractDir = resolve(import.meta.dirname, "..");

const openapiYaml = join(contractDir, "openapi.yaml");
const openapiJson = join(contractDir, "openapi.json");
const serverSpec = join(contractDir, "../server/src/generated/openapi.json");
const serverTypes = join(contractDir, "../server/src/generated/schema.d.ts");
const webTypes = join(contractDir, "../web/src/generated/schema.d.ts");

const generatedNote = "Generated from the TypeSpec sources in contract/ — do not edit it by hand.";
const regenNote = "Regenerate with: make generate";

const commentHeader = `/*\n * ${generatedNote}\n * ${regenNote}\n */\n`;

await prepend(openapiYaml, `# ${generatedNote}\n# ${regenNote}\n`);
await prepend(serverTypes, commentHeader);
await prepend(webTypes, commentHeader);
await moveJsonSpec();

async function prepend(file, header) {
  const content = await readFile(file, "utf8");
  await writeFile(file, `${header}${content}`);
}

async function moveJsonSpec() {
  const spec = JSON.parse(await readFile(openapiJson, "utf8"));
  const marked = { "x-generated": `${generatedNote} ${regenNote}`, ...spec };
  await writeFile(serverSpec, `${JSON.stringify(marked, null, 2)}\n`);
  await unlink(openapiJson);
}
